// person on the sheet has their name or an alias equal to it; blank otherwise. And the user's crew total: the due-totals of
// the crews that person leads, added up; blank when they lead none. And the REVIEW claims assigned to the user, counted. And, for a steward, a dashboard: the
// sheet's PENDING and REVIEW claims and its overdue claims that count, counted; blank for anyone else.
@Component({
  selector: 'app-header',
  template: `
    <header aria-label="Counters" data-testid="header">
      <dl>
        <div><dt>People</dt><dd data-testid="header-people-count">{{ people.people().length }}</dd></div>
        @for (s of figures.statusCounts(); track s.status) {
          <div><dt>{{ s.status }}</dt><dd [attr.data-testid]="'header-claims-' + s.status + '-count'">{{ s.count }}</dd></div>
        }
        <div><dt>Due total</dt><dd data-testid="header-due-total">{{ figures.dueTotal() }}</dd></div>
        <div><dt>Overdue total</dt><dd data-testid="header-overdue-total">{{ figures.overdueTotal() }}</dd></div>
        <div><dt>My due total</dt><dd data-testid="my-due-total">{{ figures.mine()?.dueTotal }}</dd></div>
        <div><dt>My overdue total</dt><dd data-testid="my-overdue-total">{{ figures.mine()?.overdueTotal }}</dd></div>
        <div><dt>My crew due total</dt><dd data-testid="my-crew-due-total">{{ figures.myCrewDueTotal() }}</dd></div>
        <div><dt>My reviews</dt><dd data-testid="my-reviews-count">{{ figures.myReviewsCount() }}</dd></div>
      </dl>
      <dl aria-label="Steward dashboard">
        <div><dt>Pending to approve</dt><dd data-testid="dash-pending-count">{{ figures.dashboard()?.pending }}</dd></div>
        <div><dt>To review</dt><dd data-testid="dash-review-count">{{ figures.dashboard()?.review }}</dd></div>
        <div><dt>Overdue</dt><dd data-testid="dash-overdue-count">{{ figures.dashboard()?.overdue }}</dd></div>
      </dl>
      <dl aria-label="Consolidated with descendant sheets">
        <div><dt>Consolidated people</dt><dd data-testid="consolidated-people-count">{{ consolidated().peopleCount }}</dd></div>
        <div><dt>Consolidated due total</dt><dd data-testid="consolidated-due-total">{{ consolidated().dueTotal }}</dd></div>
        <div><dt>Consolidated overdue total</dt><dd data-testid="consolidated-overdue-total">{{ consolidated().overdueTotal }}</dd></div>
        @for (g of consolidated().grades; track g.grade) {
          <div><dt>Consolidated grade {{ g.grade }} due total</dt><dd [attr.data-testid]="'consolidated-grade-' + g.grade + '-due-total'">{{ g.dueTotal }}</dd></div>
        }
import { Injectable, computed, inject } from '@angular/core';
import { Claim, Claims, bound, countsAt, isOpen, partCents, statusAt } from './claims';
import { CrewView, Crews } from './crews';
import { GRADES, People, Person, gradeOn } from './people';
import { Period, Periods } from './periods';
import { NO_RATE, Rates, halfEven, hundredths, money, rounded } from './rates';
import { Roles } from './roles';
import { Session, addDays } from './session';

/** The statuses claims are counted by, in the order the screen shows them. */
export const STATUSES = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID', 'REVIEW'] as const;

/** People's figures added up, leaving out the single highest and the single lowest when there are
 *  three or more. */
export function trimmed(figures: bigint[]): bigint {
  const sum = figures.reduce((s, f) => s + f, 0n);
  if (figures.length < 3) return sum;
  const max = figures.reduce((m, f) => (f > m ? f : m));
  const min = figures.reduce((m, f) => (f < m ? f : m));
  return sum - max - min;
}

// The due figures the screen shows, worked out in one place so the people list, the periods list,
// the summary and the header always agree.
@Injectable({ providedIn: 'root' })
export class Figures {
  private readonly claims = inject(Claims);
  private readonly crews = inject(Crews);
  private readonly people = inject(People);
  private readonly periods = inject(Periods);
  private readonly rates = inject(Rates);
  private readonly roles = inject(Roles);
  private readonly session = inject(Session);

  /** A person's due-total: the sum of their figures, at most the sheet's cap. Null (n/a) is not capped. */
  dueCents(p: Person): bigint | null {
    const sum = this.sumCents(p);
    const cap = this.capCents();
    return sum !== null && cap !== null && sum > cap ? cap : sum;
  }

  /** How far the sum of a person's figures is above the sheet's cap; 0 when it is not (or is n/a). */
  excessCents(p: Person): bigint {
    const sum = this.sumCents(p);
    const cap = this.capCents();
    return sum !== null && cap !== null && sum > cap ? sum - cap : 0n;
  }

  private capCents(): bigint | null {
    const cap = this.session.cap();
    return cap === null ? null : hundredths(cap);
  }

  /** The sum of the figures of a person's claims that count live (not left out by a hold), less the parts others
   *  hold of them, and the parts they hold of other people's: a settled claim's frozen due, else the
   *  figure their last statement bound it to, else its live due at the rate in force on its date (a
   *  claim with no figure adds nothing). Null when the grade in force on the sheet's today has no rate
   *  there and no claim has a figure. */
  sumCents(p: Person): bigint | null {
    let sum = 0n;
    if (!user || this.steward()) return null;
    if (!this.roles.roles().some((r) => r.user === user && r.role === 'restricted')) return null;
    const loaded = this.people.loadedIds();
    const ids = new Set<number>(this.people.people().filter((o) => !loaded.has(o.id)).map((o) => o.id));
    const p = this.me();
    if (!p) return ids;
    ids.add(p.id);
    for (const c of this.crews.crews()) {
      const crew = [...(c.lead ? [c.lead.personId] : []), ...c.members.map((m) => m.personId)];
      if (crew.includes(p.id)) crew.forEach((id) => ids.add(id));
    }
    return ids;
  });

  /** A steward's dashboard: the sheet's PENDING and REVIEW claims and its overdue claims that count,
   *  counted; null when the signed-in user is not a steward. */
  readonly dashboard = computed(() => {
    if (!this.steward()) return null;
    const claims = this.claims.claims();
    return {
      pending: claims.filter((c) => c.status === 'PENDING').length,
      review: claims.filter((c) => c.status === 'REVIEW').length,
      overdue: this.claims.live().filter((c) => this.claims.overdue(c)).length,
    };
  });

  /** How many of the sheet's REVIEW claims are assigned to the signed-in user, names compared trimmed and
   *  without regard to case. */
  readonly myReviewsCount = computed(() => {
    const user = this.session.user()?.trim().toLowerCase();
    if (!user) return 0;
    return this.claims.claims().filter((c) => c.status === 'REVIEW' && c.reviewAssignee?.trim().toLowerCase() === user)
      .length;
  });

  /** A crew's due-total: the lead's and the members' due-totals as the people list shows them, added up,
   *  n/a skipped. */
  crewDueCents(c: CrewView): bigint {
    const ids = new Set([...(c.lead ? [c.lead.personId] : []), ...c.members.map((m) => m.personId)]);
    let sum = 0n;
    for (const p of this.people.people()) {
      if (!ids.has(p.id)) continue;
      const d = this.dueCents(p);
      if (d !== null) sum += d;
    }
    return sum;
  }

  /** The signed-in user's crew total: the due-totals of the crews the person with the user's name leads,
   *  added up; null when there is no such person or they lead no crew. */
  readonly myCrewDueTotal = computed(() => {
    const p = this.me();
    if (!p) return null;
    const led = this.crews.crews().filter((c) => c.lead?.personId === p.id);
    if (led.length === 0) return null;
    return money(led.reduce((sum, c) => sum + this.crewDueCents(c), 0n));
  });

  /** Each tag ever used on the sheet (on a claim or a person), sorted, with the due of the claims that
   *  count live and carry it, or whose person carries it, once each (a claim with two tags counts in both),
   *  not capped or trimmed. */
  readonly tagTotals = computed(() => {
    const byId = new Map(this.people.people().map((p) => [p.id, p]));
    const used = [...new Set([...this.claims.usedTags(), ...this.people.people().flatMap((p) => p.tags)])].sort();
    const sums = new Map<string, bigint>(used.map((t) => [t, 0n]));
    for (const c of this.claims.live()) {
      const p = byId.get(c.personId);
      if (!p) continue;
      const due = this.figureCents(c, p);
      for (const t of new Set([...c.tags, ...p.tags])) sums.set(t, (sums.get(t) ?? 0n) + due);
    }
    return [...sums].map(([tag, cents]) => ({ tag, dueTotal: money(cents) }));
  });

  /** Each calendar month (yyyy-mm) any claim on the sheet is dated in, in order, with the due of the
   *  claims dated in it that count live, not capped or trimmed. */
  readonly monthTotals = computed(() => {
    const byId = new Map(this.people.people().map((p) => [p.id, p]));
    const months = [...new Set(this.claims.claims().map((c) => c.date.slice(0, 7)))].sort();
    const sums = new Map<string, bigint>(months.map((m) => [m, 0n]));
    for (const c of this.claims.live()) {
      const p = byId.get(c.personId);
      const month = c.date.slice(0, 7);
      if (!p || !sums.has(month)) continue;
      sums.set(month, sums.get(month)! + this.figureCents(c, p));
    }
    return [...sums].map(([month, cents]) => ({ month, dueTotal: money(cents) }));
  });

  /** The number of claims in each status, in the order of STATUSES. */
  readonly statusCounts = computed(() => {
    const claims = this.claims.claims();
    return STATUSES.map((status) => ({ status, count: claims.filter((c) => c.status === status).length }));
  });

  /** A person's claims that count live and are overdue. */
  overdue(p: Person): Claim[] {
    return this.claims.live().filter((c) => c.personId === p.id && this.claims.overdue(c));
  }

  /** A person's score: their settled figures (corrections left out) divided by 100, less 5 for every overdue claim of theirs
  /** The last statement's date: the sheet's today when it was taken, or the date it was taken as of; null
   *  before their first. */
  statementDate: string | null;
  /** Whether a retirement date is set: then they count as retired at once, whatever the date. */
  retired: boolean;
  /** The date they are retired from (YYYY-MM-DD); null while not retired. */
  retiredFrom: string | null;
  /** Their past retirements, by from-date. */
  retirements: Retirement[];
  /** Whether they have any hold at all. */
  held: boolean;
  /** Their holds, by from-date: an OPEN or PENDING claim dated within one, and bound by no statement,
   *  counts in no live total. */
  holds: Hold[];
  /** The ids of the other people on the sheet they have named as their patrons. */
  patronIds: number[];
  /** Whether the signed-in user watches them. */
  watched: boolean;
  /** Their own terms in days in force on the sheet's today, ahead of their grade's and the sheet's; null
   *  when they have none then. */
  terms: number | null;
  /** Their own terms from the beginning of time; null when they have none. */
  baseTerms: number | null;
  /** Their own terms recorded from a date, by from-date; terms null for none of their own. */
  datedTerms: { terms: number | null; from: string }[];
  /** Their contact, trimmed and lower-cased; null when they have none. */
  contact: string | null;
  /** The other names they go by, sorted as names are compared: without regard to case. */
  aliases: string[];
  /** Whether their name or an alias is used on another sheet of the sheet's tree: every save of the person
   *  form is refused until a rename leaves them clashing with no one. */
  clashing: boolean;
  /** The sheet they were transferred from; null for anyone added on this sheet. */
  origin: string | null;
  /** Their tags: trimmed, lower-cased, without repeats, sorted; empty when they carry none. */
  tags: string[];
  /** Their snapshot lines, oldest first: one per day the sheet's today moved on from, as
   *  `<the day being left> <due-total>` (n/a when it was). */
  snapshots: string[];
  /** Their statement lines, one per statement standing, oldest first by date, as
   *  `<statement date> <due-total>` (n/a when it was). */

